window.PRONUNCIATION_INDEX.push(...[{"id": "ab078-t01", "text": "Ich steige jetzt in die U-Bahn ein.", "type": "sentence"}, {"id": "ab078-t02", "text": "Wie heißen die Wörter? Ergänzen Sie.", "type": "sentence"}, {"id": "ab078-t03", "text": "Wann sind wir am Flughafen? — In 40 Minuten.", "type": "sentence"}, {"id": "ab078-t04", "text": "Wie heißt der nächste Halt? — Mönckebergstraße.", "type": "sentence"}, {"id": "ab078-t05", "text": "Vorsicht an der Bahnsteigkante. Der Zug fährt ab. — Zu spät! Jetzt nehmen wir den nächsten Zug.", "type": "sentence"}, {"id": "ab078-t06", "text": "Ich suche die U2 zum Olympiazentrum. — Die Bahn fährt gerade am Bahnsteig 5 ein.", "type": "sentence"}, {"id": "ab078-t07", "text": "Ergänzen Sie die Verben.", "type": "sentence"}, {"id": "ab078-t08", "text": "ankommen · anrufen · einsteigen · fernsehen · einkaufen · aussteigen", "type": "sentence"}, {"id": "ab078-t09", "text": "Markieren Sie die Verben und notieren Sie den Infinitiv.", "type": "sentence"}, {"id": "ab078-t10", "text": "Liebe Susi, ich kaufe heute ein! Dann kochen wir und dann sehen wir noch ein bisschen fern, ok?", "type": "sentence"}, {"id": "ab078-t11", "text": "Hallo Herr Peters, Frau Alvarez kommt heute um 17.35 Uhr am Flughafen an. Sie wohnt im Hotel „Am Stadtpark“. Viele Grüße, Bianca Schwiering", "type": "sentence"}, {"id": "ab078-t12", "text": "Hallo Andrea, hier meine Adresse: Humboldtstraße 121a. Ich steige immer am Kolumbusplatz aus. Dann sind es nur 5 Min. Bis bald, Martin", "type": "sentence"}, {"id": "ab078-t13", "text": "Gehen wir heute in die Disco? Die „Wunderbar“ finde ich echt gut. Ich rufe dich an.", "type": "sentence"}, {"id": "ab079-t01", "text": "Trennbar oder nicht? Ergänzen Sie, wo nötig.", "type": "sentence"}, {"id": "ab079-t02", "text": "Steigt ihr am Goetheplatz ein?", "type": "sentence"}, {"id": "ab079-t03", "text": "Wann telefonierst du mit Oma?", "type": "sentence"}, {"id": "ab079-t04", "text": "Heute Abend sehen wir fern. Kommst du auch?", "type": "sentence"}, {"id": "ab079-t05", "text": "Wo steigt ihr um?", "type": "sentence"}, {"id": "ab079-t06", "text": "Bekomme ich bitte einen Kaffee?", "type": "sentence"}, {"id": "ab079-t07", "text": "Vielleicht bringe ich am Samstag meine Freundin mit.", "type": "sentence"}, {"id": "ab079-t08", "text": "Am Sonntag frühstücke ich erst um 12 Uhr.", "type": "sentence"}, {"id": "ab079-t09", "text": "Schreiben Sie eigene Sätze wie in 4 und tauschen Sie mit Ihrer Partnerin / Ihrem Partner.", "type": "sentence"}, {"id": "ab079-t10", "text": "Schreiben Sie Sätze.", "type": "sentence"}, {"id": "ab079-t11", "text": "Wir steigen am Rathausplatz aus.", "type": "sentence"}, {"id": "ab079-t12", "text": "Wo fährt der Zug nach Berlin ab?", "type": "sentence"}, {"id": "ab079-t13", "text": "Rufst du mich an?", "type": "sentence"}, {"id": "ab079-t14", "text": "Ich hole dich um 16.45 Uhr ab.", "type": "sentence"}, {"id": "ab079-t15", "text": "Bringt ihr einen Kuchen mit?", "type": "sentence"}, {"id": "ab079-t16", "text": "Wann kommt der Bus an?", "type": "sentence"}, {"id": "ab079-t17", "text": "Fremd in der Stadt. Was denkt Jutta? Schreiben Sie.", "type": "sentence"}, {"id": "ab079-t18", "text": "Wie komme ich jetzt zu „Schulz und Partner“?", "type": "sentence"}, {"id": "ab079-t19", "text": "Zentrum Köln → „Schulz und Partner“ (Praktikum Mo–Fr) – am Flughafen in die S-Bahn einsteigen – am Hauptbahnhof in die U-Bahn umsteigen – am Eifelplatz aussteigen – Frau Lerch anrufen", "type": "sentence"}, {"id": "ab079-t20", "text": "Also, ich steige am Flughafen in die S-Bahn ein. Am Hauptbahnhof steige ich in die U-Bahn um. Am Eifelplatz steige ich aus und rufe Frau Lerch an.", "type": "sentence"}, {"id": "ab080-t01", "text": "Ergänzen Sie und vergleichen Sie.", "type": "sentence"}, {"id": "ab080-t02", "text": "Flugzeug · Taxi · Straßenbahn · Zug · U-Bahn · Bus", "type": "sentence"}, {"id": "ab080-t03", "text": "der Zug – train · das Flugzeug – plane · das Taxi – taxi · die Straßenbahn – tram, streetcar · der Bus – bus · die U-Bahn – underground", "type": "sentence"}, {"id": "ab080-t04", "text": "Mike in München, Teil 1 — Ordnen Sie die Fragen zu.", "type": "sentence"}, {"id": "ab080-t05", "text": "Wann kommst du? · Holst du mich ab? · Nimmst du den Zug? · Hast du Zeit?", "type": "sentence"}, {"id": "ab080-t06", "text": "Hallo Tom, hier ist Mike. — Hallo Mike, wie geht's?", "type": "sentence"}, {"id": "ab080-t07", "text": "Gut, danke. Ich bin nächste Woche in München und möchte dich gern besuchen. Hast du Zeit?", "type": "sentence"}, {"id": "ab080-t08", "text": "Ja natürlich! Wann kommst du? — Am Mittwoch, um 20:50 Uhr.", "type": "sentence"}, {"id": "ab080-t09", "text": "Nimmst du den Zug? — Ja. Ich komme am Ostbahnhof an. Holst du mich ab?", "type": "sentence"}, {"id": "ab080-t10", "text": "Na klar, gern. Ich arbeite bis 20 Uhr. Dann hole ich dich ab. — Danke, dann bis Mittwoch!", "type": "sentence"}, {"id": "ab080-t11", "text": "Mike in München, Teil 2 — Hören Sie. Was ist richtig? Kreuzen Sie an. (CD 1, Track 43)", "type": "sentence"}, {"id": "ab080-t12", "text": "Wann ist Mike in München? — Um 18:30 Uhr. / Um 19:00 Uhr.", "type": "sentence"}, {"id": "ab080-t13", "text": "Mike fährt — zum Flughafen. / nach Daglfing.", "type": "sentence"}, {"id": "ab080-t14", "text": "Er nimmt — die S-Bahn. / die U-Bahn.", "type": "sentence"}, {"id": "ab080-t15", "text": "Wie lange dauert die Fahrt? — 20 Minuten / 7 Minuten", "type": "sentence"}, {"id": "ab080-t16", "text": "Was bringt Mike mit? — Wurst / Brot", "type": "sentence"}, {"id": "ab081-t01", "text": "Wo sind die Personen? Hören Sie und kreuzen Sie an. (CD 1, Tracks 44-46)", "type": "sentence"}, {"id": "ab081-t02", "text": "Durchsage 1 · Durchsage 2 · Durchsage 3", "type": "sentence"}, {"id": "ab081-t03", "text": "Durchsagen — Lesen Sie die Aufgaben. Markieren Sie alle Zahlen und Uhrzeiten.", "type": "sentence"}, {"id": "ab081-t04", "text": "Die Passagiere von Flug 134 können jetzt einsteigen. / Die Passagiere von Flug 243 können jetzt einsteigen.", "type": "sentence"}, {"id": "ab081-t05", "text": "Die U5 fährt am Montag nur bis zum Ostbahnhof. / Der Bus Nr. 58 fährt am Montag nur bis zum Ostbahnhof.", "type": "sentence"}, {"id": "ab081-t06", "text": "Der ICE 756 aus Hamburg kommt heute um 13:27 Uhr an. / Der ICE 756 aus Hamburg kommt heute um 13:50 Uhr an.", "type": "sentence"}, {"id": "ab081-t07", "text": "Tipp: Achten Sie auf Zahlen und Uhrzeiten. Am Bahnhof und Flughafen müssen Sie Zahlen und Zeiten richtig verstehen.", "type": "sentence"}, {"id": "ab081-t08", "text": "Hören Sie noch einmal. Welche Sätze sind richtig? Kreuzen Sie in a an.", "type": "sentence"}, {"id": "ab081-t09", "text": "Wortakzent bei trennbaren Verben — Hören Sie und markieren Sie den Wortakzent. (CD 1, Track 47)", "type": "sentence"}, {"id": "ab081-t10", "text": "fahren – abfahren · kommen – ankommen · kaufen – einkaufen · sehen – fernsehen · bringen – mitbringen", "type": "sentence"}, {"id": "ab081-t11", "text": "Hören Sie noch einmal und sprechen Sie nach. (CD 1, Track 48)", "type": "sentence"}, {"id": "ab081-t12", "text": "Richtig oder falsch? Kreuzen Sie an. — Regel: Der Wortakzent ist bei trennbaren Verben auf dem trennbaren Wortteil.", "type": "sentence"}, {"id": "ab081-t13", "text": "Hören Sie. Sprechen Sie dann. (CD 1, Track 49)", "type": "sentence"}, {"id": "ab081-t14", "text": "Ich nehme heut' den Zug. Einsteigen. Aussteigen. Umsteigen. Vorsicht an Gleis sieben!", "type": "sentence"}, {"id": "ab081-t15", "text": "Ich nehme heut' den Zug. Abfahren. Ankommen. Anrufen. Holst du mich bitte ab?", "type": "sentence"}, {"id": "ab082-t01", "text": "Wie heißen die Wörter?", "type": "sentence"}, {"id": "ab082-t02", "text": "Ordnen Sie zu.", "type": "sentence"}, {"id": "ab082-t03", "text": "Guten Tag, Herr Baltaci. Haben Sie Gepäck? — Ja, zwei Koffer und die Tasche.", "type": "sentence"}, {"id": "ab082-t04", "text": "Nächster Halt Königsplatz.", "type": "sentence"}, {"id": "ab082-t05", "text": "Wo fährt der Zug nach Stuttgart ab? — Auf Gleis 17.", "type": "sentence"}, {"id": "ab082-t06", "text": "Es ist schon sehr spät. Jetzt fährt keine U-Bahn mehr. — Dann nehmen wir ein Taxi.", "type": "sentence"}, {"id": "ab082-t07", "text": "Ergänzen Sie das Gespräch.", "type": "sentence"}, {"id": "ab082-t08", "text": "Guten Morgen Ella, hier ist Karin. Wo bist du? — Hallo Karin. Ich steige gerade in den Zug ein.", "type": "sentence"}, {"id": "ab082-t09", "text": "Wann kommst du an? — Um 09.35 Uhr am Ostbahnhof und um 09.45 Uhr am Hauptbahnhof.", "type": "sentence"}, {"id": "ab082-t10", "text": "Kannst du bitte am Hauptbahnhof aussteigen? Ich hole dich ab. — Super, vielen Dank.", "type": "sentence"}, {"id": "ab082-t11", "text": "Jetzt kaufe ich Brötchen ein, dann können wir zusammen frühstücken. — Gute Idee. Also dann, bis bald.", "type": "sentence"}, {"id": "ab082-t12", "text": "Schreiben Sie vier Gespräche.", "type": "sentence"}, {"id": "ab082-t13", "text": "Wo fährt der Zug nach Köln ab? — Auf Gleis 15.", "type": "sentence"}, {"id": "ab082-t14", "text": "Wann kommt der Zug an? — Um 09:45 Uhr.", "type": "sentence"}, {"id": "ab082-t15", "text": "Holst du mich ab? — Ich habe leider keine Zeit.", "type": "sentence"}, {"id": "ab082-t16", "text": "Wo steigst du um? — Am Rathausplatz.", "type": "sentence"}, {"id": "ab082-t17", "text": "Nehmt ihr ein Taxi? — Nein, die U-Bahn.", "type": "sentence"}, {"id": "ab083-t01", "text": "Lernwortschatz — Wie heißen die Wörter in Ihrer Sprache? Übersetzen Sie.", "type": "sentence"}, {"id": "ab083-t02", "text": "Verkehr und Reisen: der Bahnhof · der Bahnsteig · der Bus · der Halt · die Haltestelle · der Flughafen · das Flugzeug · das Gepäck · das Gleis · der Koffer · die S-Bahn · die Straßenbahn / die Tram · das Taxi · die U-Bahn · das Verkehrsmittel · der Zug", "type": "sentence"}, {"id": "ab083-t03", "text": "abfahren · abholen · ankommen · aussteigen · einsteigen · umsteigen", "type": "sentence"}, {"id": "ab083-t04", "text": "Weitere wichtige Wörter: die Minute · die Vorsicht · zu Hause · Entschuldigen Sie. · anrufen · bekommen · einkaufen · fernsehen · mitbringen · nehmen · also · also dann · gerade · nächste · viel · auf · auf Gleis 10 · bis · Bis bald!", "type": "sentence"}, {"id": "ab083-t05", "text": "Tipp: Sie lesen den Satz: „Wir steigen dann in Flensburg in den Bus um.“ Sie verstehen „steigen“ nicht und suchen im Wörterbuch. Achten Sie auch auf das Satzende. Suchen Sie „umsteigen“ im Wörterbuch.", "type": "sentence"}, {"id": "ab083-t06", "text": "Welche Wörter möchten Sie noch lernen? Notieren Sie.", "type": "sentence"}, {"id": "ab084-t01", "text": "Was hast du heute gemacht?", "type": "sentence"}, {"id": "ab084-t02", "text": "Was macht Lisa? Ergänzen Sie um – am – von … bis – ab.", "type": "sentence"}, {"id": "ab084-t03", "text": "Am Montag frühstückt Lisa um 7 Uhr.", "type": "sentence"}, {"id": "ab084-t04", "text": "Ab 8 Uhr arbeitet sie.", "type": "sentence"}, {"id": "ab084-t05", "text": "Von 18 bis 19 Uhr kauft sie ein und kocht.", "type": "sentence"}, {"id": "ab084-t06", "text": "Am Abend geht sie mit Klaus ins Kino.", "type": "sentence"}, {"id": "ab084-t07", "text": "Was machen Sie heute? Ergänzen Sie den Kalender. Ihre Partnerin / Ihr Partner schreibt einen kurzen Text wie in 1.", "type": "sentence"}, {"id": "ab084-t08", "text": "Was machst du gern? Wie heißen die Verben?", "type": "sentence"}, {"id": "ab084-t09", "text": "machen · schlafen · fernsehen · fahren · aufräumen · lesen · lernen", "type": "sentence"}, {"id": "ab084-t10", "text": "Ergänzen Sie die Verben aus a in der richtigen Form.", "type": "sentence"}, {"id": "ab084-t11", "text": "Siehst du am Abend gern fern?", "type": "sentence"}, {"id": "ab084-t12", "text": "Räumst du gern deine Wohnung auf?", "type": "sentence"}, {"id": "ab084-t13", "text": "Schläfst du am Wochenende lange?", "type": "sentence"}, {"id": "ab084-t14", "text": "Liest du gern Zeitung?", "type": "sentence"}, {"id": "ab084-t15", "text": "Fährst du gern Fahrrad?", "type": "sentence"}, {"id": "ab084-t16", "text": "Lernst du gern Deutsch?", "type": "sentence"}, {"id": "ab084-t17", "text": "Machst du gern Hausaufgaben?", "type": "sentence"}, {"id": "ab084-t18", "text": "Ergänzen Sie haben in der richtigen Form.", "type": "sentence"}, {"id": "ab084-t19", "text": "Haben wir jetzt alles für die Party? — Ich denke ja.", "type": "sentence"}, {"id": "ab084-t20", "text": "Hast du auch Brot gekauft? — Ja klar. Das habe ich doch heute Morgen schon gekauft.", "type": "sentence"}, {"id": "ab084-t21", "text": "Und wo ist der Geburtstagskuchen? — Den Kuchen hat Julia gebacken. Sie bringt ihn heute Abend zur Party mit.", "type": "sentence"}, {"id": "ab084-t22", "text": "Sehr gut. Und was haben wir zu trinken? — Wein, Mineralwasser und Saft.", "type": "sentence"}, {"id": "ab084-t23", "text": "Super! Und wo habt ihr das Geschenk für Julia? — Das ist noch in Claudias Auto. Sie kommt um sechs Uhr und bringt es mit.", "type": "sentence"}, {"id": "ab084-t24", "text": "Gut, ich glaube, jetzt haben wir wirklich alles.", "type": "sentence"}, {"id": "ab085-t01", "text": "Ergänzen Sie haben und das Partizip.", "type": "sentence"}, {"id": "ab085-t02", "text": "gelernt · gegessen · eingeladen · gebacken · geschlafen · gekauft · gelesen", "type": "sentence"}, {"id": "ab085-t03", "text": "Am Sonntag habe ich lange geschlafen.", "type": "sentence"}, {"id": "ab085-t04", "text": "Wo haben Sie Deutsch gelernt?", "type": "sentence"}, {"id": "ab085-t05", "text": "Ich habe Kuchen gebacken.", "type": "sentence"}, {"id": "ab085-t06", "text": "Hast du deine Schwester auch zu deiner Party eingeladen?", "type": "sentence"}, {"id": "ab085-t07", "text": "Was habt ihr zum Mittagessen gegessen?", "type": "sentence"}, {"id": "ab085-t08", "text": "Gestern habe ich ein neues Fahrrad gekauft.", "type": "sentence"}, {"id": "ab085-t09", "text": "Ich habe heute noch nicht Zeitung gelesen.", "type": "sentence"}, {"id": "ab085-t10", "text": "Wiederholung: Verben — Ordnen Sie zu und ergänzen Sie den Infinitiv.", "type": "sentence"}, {"id": "ab085-t11", "text": "gearbeitet–arbeiten · gewohnt–wohnen · geglaubt–glauben · gesucht–suchen · gekostet–kosten · gesagt–sagen · gebraucht–brauchen · gelacht–lachen · gefrühstückt–frühstücken · gelernt–lernen · geliebt–lieben · angerufen–anrufen · eingekauft–einkaufen · aufgeräumt–aufräumen · geredet–reden", "type": "sentence"}, {"id": "ab085-t12", "text": "gesprochen–sprechen · gefunden–finden · geschrieben–schreiben · gewusst–wissen · eingeladen–einladen · gesungen–singen · gesehen–sehen · getrunken–trinken · genommen–nehmen · gedacht–denken", "type": "sentence"}, {"id": "ab085-t13", "text": "Finden Sie die Partizipien und ergänzen Sie. Dennis hat letzten Freitag …", "type": "sentence"}, {"id": "ab085-t14", "text": "eine E-Mail geschrieben · Musik gehört · Tennis gespielt · seine Freundin am Bahnhof abgeholt · Freunde in einem Café getroffen · Abendessen gekocht · in der Disco getanzt", "type": "sentence"}, {"id": "ab086-t01", "text": "Antworten Sie auf die SMS. Verwenden Sie das Perfekt.", "type": "sentence"}, {"id": "ab086-t02", "text": "einkaufen · abholen · einladen · mitbringen", "type": "sentence"}, {"id": "ab086-t03", "text": "Hi Claudia, holst du bitte Paula am Bahnhof ab? Ich habe keine Zeit. LG Max", "type": "sentence"}, {"id": "ab086-t04", "text": "Hallo Max, ich habe Paula schon abgeholt. Sie hat super Wein mitgebracht! Wir sind schon zu Hause. Grüße Claudia", "type": "sentence"}, {"id": "ab086-t05", "text": "Das ist sehr nett! Essen wir heute Abend zusammen?", "type": "sentence"}, {"id": "ab086-t06", "text": "Ja natürlich! Wir haben eingekauft und kochen jetzt. Wir haben auch Susanne zum Essen eingeladen. Okay?", "type": "sentence"}, {"id": "ab086-t07", "text": "Eine E-Mail aus Hamburg. Lesen Sie und kreuzen Sie an.", "type": "sentence"}, {"id": "ab086-t08", "text": "An: Chiara1312@freenet.de · Kopie: nina@aol.com · Betreff: neuer Job", "type": "sentence"}, {"id": "ab086-t09", "text": "Hallo Nina, wie geht es dir? Du hast so lange nicht geschrieben. Ist alles okay?", "type": "sentence"}, {"id": "ab086-t10", "text": "Ich habe im Mai bei einer neuen Firma als Marketing-Assistentin angefangen. Der Job ist sehr interessant und meine Kollegen sind sehr nett und lustig. In der Mittagspause essen wir immer zusammen, reden und lachen viel. Aber ich habe auch sehr viel Arbeit. Ich arbeite täglich von 8.30 Uhr bis 17.30 oder 18.00 Uhr und manchmal arbeite ich auch noch länger.", "type": "sentence"}, {"id": "ab086-t11", "text": "Nach der Arbeit gehe ich oft mit meinen Kolleginnen und Kollegen noch in eine Kneipe, ins Kino oder wir treffen uns bei meiner Kollegin Tamara. Sie hat eine sehr große und schöne Wohnung und sie kocht gern für viele Leute. Das finde ich super! Sie hat viele nette Freunde, wie zum Beispiel Rainer … aber mehr Info zu Rainer in der nächsten Mail …", "type": "sentence"}, {"id": "ab086-t12", "text": "Bitte schreib mir! Herzliche Grüße, Chiara", "type": "sentence"}, {"id": "ab086-t13", "text": "Chiara … richtig / falsch: a hat eine neue Arbeit. b hat viel Spaß mit ihren Kollegen. c arbeitet jeden Tag bis 19 Uhr. d geht am Abend immer mit ihren Kollegen in Kneipen. e besucht gern ihre Kollegin Tamara. f findet Rainer nett.", "type": "sentence"}, {"id": "ab087-t01", "text": "Einen Tagesablauf beschreiben — Lesen Sie Susanas E-Mail.", "type": "sentence"}, {"id": "ab087-t02", "text": "Liebe Christina, wie geht es dir denn in deinem neuen Job als Au-pair-Mädchen in Köln? Was machst du den ganzen Tag? Hast du viel Arbeit? Viele Grüße, Susana", "type": "sentence"}, {"id": "ab087-t03", "text": "Christinas Tag. Ordnen Sie die Verben den Bildern zu.", "type": "sentence"}, {"id": "ab087-t04", "text": "im Supermarkt einkaufen · mit Freunden kochen · schlafen · zusammen essen · Frühstück machen · Wohnung aufräumen", "type": "sentence"}, {"id": "ab087-t05", "text": "Schreiben Sie Christinas E-Mail mit den Wörtern aus a.", "type": "sentence"}, {"id": "ab087-t06", "text": "Liebe Susana, vielen Dank für deine E-Mail. Mir geht es sehr gut. Ich habe viel Arbeit, aber die Familie ist sehr nett. Das habe ich zum Beispiel heute gemacht: Um acht Uhr habe ich für die Familie Frühstück gemacht. … Ich schreibe bald wieder. Viele Grüße, Christina", "type": "sentence"}, {"id": "ab087-t07", "text": "Regel: Kontrollieren Sie noch einmal Ihren Text. Sind die Verben an der richtigen Position?", "type": "sentence"}, {"id": "ab087-t08", "text": "Satzakzent in Sätzen mit Perfekt — Hören Sie und sprechen Sie nach. (CD 1, Track 50)", "type": "sentence"}, {"id": "ab087-t09", "text": "Am Abend — Was hast du heute gemacht? — Heute? Nicht viel. Ich habe gelesen.", "type": "sentence"}, {"id": "ab087-t10", "text": "Gelesen? Was denn? — Ich habe ein Buch gelesen. Und ich habe aufgeräumt.", "type": "sentence"}, {"id": "ab087-t11", "text": "Aufgeräumt? Das Bad? — Nein. Nicht das Bad. Ich habe die Küche aufgeräumt. Und ich habe ein bisschen gelernt.", "type": "sentence"}, {"id": "ab087-t12", "text": "Gelernt? Was denn? — Ich habe natürlich Deutsch gelernt.", "type": "sentence"}, {"id": "ab087-t13", "text": "Schreiben und sprechen Sie eigene Gespräche im Perfekt.", "type": "sentence"}, {"id": "ab088-t01", "text": "Was passt? Ordnen Sie zu.", "type": "sentence"}, {"id": "ab088-t02", "text": "Wein trinken · die Hausaufgaben machen · Fahrrad fahren · Spanisch lernen · die Zeitung lesen · Freunde einladen · das Zimmer aufräumen", "type": "sentence"}, {"id": "ab088-t03", "text": "Schreiben Sie Sätze im Perfekt.", "type": "sentence"}, {"id": "ab088-t04", "text": "Hast du heute gearbeitet? — Ja, aber nur bis 14 Uhr. Am Nachmittag habe ich Fußball gespielt.", "type": "sentence"}, {"id": "ab088-t05", "text": "Hast du Monika gesehen? — Ja, letzte Woche. Wir haben viel gelacht.", "type": "sentence"}, {"id": "ab088-t06", "text": "Habt ihr heute Nachmittag eingekauft? — Nein, Anna hat Englisch gelernt und ich habe Hausaufgaben gemacht.", "type": "sentence"}, {"id": "ab088-t07", "text": "Was hast du zum Frühstück gegessen? — Müsli. Und ich habe einen Kaffee getrunken.", "type": "sentence"}, {"id": "ab088-t08", "text": "Was hast du heute gemacht? — Nicht viel. Ich habe bis 12 Uhr geschlafen. Gestern haben meine Freunde und ich lange gefeiert.", "type": "sentence"}, {"id": "ab088-t09", "text": "Ergänzen Sie den Chat. Schreiben Sie.", "type": "sentence"}, {"id": "ab088-t10", "text": "NEYLA: Hallo Kelubia, wie geht's? Was hast du denn heute alles gemacht?", "type": "sentence"}, {"id": "ab088-t11", "text": "Kelubia: Ach, ich habe lange geschlafen. Dann habe ich eingekauft. Von 15 bis 17 Uhr habe ich Tennis gespielt. Und du? Was hast du heute gemacht?", "type": "sentence"}, {"id": "ab088-t12", "text": "NEYLA: Am Vormittag habe ich mit Anna Deutsch gelernt und am Nachmittag habe ich gearbeitet. Jetzt räume ich noch auf, dann gehe ich schlafen.", "type": "sentence"}, {"id": "ab088-t13", "text": "Kelubia: Na, dann – gute Nacht!", "type": "sentence"}, {"id": "ab089-t01", "text": "Lernwortschatz — Wie heißen die Wörter in Ihrer Sprache? Übersetzen Sie.", "type": "sentence"}, {"id": "ab089-t02", "text": "Mein Tag: die Arbeit · die Hausaufgabe (machen) · die Pause (machen) · die Zeitung · aufräumen · einladen · kaufen · lachen · lernen · reden · schlafen · täglich · ab · von … bis", "type": "sentence"}, {"id": "ab089-t03", "text": "Weitere wichtige Wörter: das Baby · das Fahrrad (fahren) · das Geschenk · der Monat · das Paar · die Party · die Reise (Dienstreise / Privatreise) · der Sport · der Wein · denken · meinen · fertig (sein) · interessant · lange · langweilig · letzt- (letzten Freitag / letztes Jahr / letzte Woche) · schwanger · für · … mal (zwei-/drei-/viermal) · Wirklich?", "type": "sentence"}, {"id": "ab089-t04", "text": "Tipp: Schreiben Sie Sätze. Benutzen Sie neue und alte Wörter.", "type": "sentence"}, {"id": "ab089-t05", "text": "Welche Wörter möchten Sie noch lernen? Notieren Sie.", "type": "sentence"}, {"id": "ab090-t01", "text": "Was ist denn hier passiert?", "type": "sentence"}, {"id": "ab090-t02", "text": "Monate und Jahreszeiten — Ergänzen und vergleichen Sie. Ordnen Sie dann die Bilder zu.", "type": "sentence"}, {"id": "ab090-t03", "text": "der Winter – Januar, Februar, März · der Frühling – April, Mai, Juni · der Sommer – Juli, August, September · der Herbst – Oktober, November, Dezember", "type": "sentence"}, {"id": "ab090-t04", "text": "Welche Jahreszeit, welcher Monat ist das?", "type": "sentence"}, {"id": "ab090-t05", "text": "Machen Sie eigene Aufgaben wie in b und tauschen Sie mit Ihrer Partnerin / Ihrem Partner.", "type": "sentence"}, {"id": "ab090-t06", "text": "Jahreszahlen und Monate — Welche Jahreszahlen hören Sie? Kreuzen Sie an. Wie heißt das Lösungswort? (CD 1, Track 51)", "type": "sentence"}, {"id": "ab090-t07", "text": "1789 / 1798 · 2017 / 2170 · 1980 / 1918 · 1576 / 1376 · 2011 / 2001 · 313 / 333 — Lösungswort: HERBST", "type": "sentence"}, {"id": "ab090-t08", "text": "Wie heißt die Jahreszahl? Lesen Sie laut. Hören und vergleichen Sie dann. (CD 1, Track 52)", "type": "sentence"}, {"id": "ab090-t09", "text": "2054 · 1255 · 1966 · 1832 · 2001", "type": "sentence"}, {"id": "ab090-t10", "text": "Wann haben die Personen Geburtstag? — Hanne: 14.05. — im Mai · Bernd: 26.04. — im April · Sabine: 23.02. — im Februar · Florian: 31.08. — im August", "type": "sentence"}, {"id": "ab091-t01", "text": "Ergänzen Sie sein in der richtigen Form.", "type": "sentence"}, {"id": "ab091-t02", "text": "Marc ist nach New York geflogen.", "type": "sentence"}, {"id": "ab091-t03", "text": "Ich bin mit Daniel in ein Konzert gegangen.", "type": "sentence"}, {"id": "ab091-t04", "text": "Seid ihr schon einmal nach Zürich gefahren?", "type": "sentence"}, {"id": "ab091-t05", "text": "Oksana und Marijana sind am Montag nicht in den Deutschkurs gekommen.", "type": "sentence"}, {"id": "ab091-t06", "text": "Bist du nach Hamburg gefahren oder geflogen?", "type": "sentence"}, {"id": "ab091-t07", "text": "Wie heißt der Infinitiv? Notieren Sie.", "type": "sentence"}, {"id": "ab091-t08", "text": "Liebe Freunde, ich bin wieder zu Hause! Portugal war wirklich super. Ich bin viel im Atlantik geschwommen und viel Rad gefahren. Leider war die Fahrt sehr lang. Am Freitagabend bin ich in Porto abgefahren und erst am Sonntagmittag in Frankfurt angekommen (und dreimal umgestiegen …). Nächste Woche feiern wir, es gibt Wein aus Portugal! Björn", "type": "sentence"}, {"id": "ab091-t09", "text": "geschwommen–schwimmen · gefahren–fahren · abgefahren–abfahren · angekommen–ankommen · umgestiegen–umsteigen", "type": "sentence"}, {"id": "ab091-t10", "text": "Ergänzen Sie die Tabelle mit den Verben aus 3 und 4.", "type": "sentence"}, {"id": "ab091-t11", "text": "sein + ge…en: fliegen–geflogen · gehen–gegangen · fahren–gefahren · kommen–gekommen · schwimmen–geschwommen", "type": "sentence"}, {"id": "ab091-t12", "text": "sein + (…)ge…en: abfahren–abgefahren · ankommen–angekommen · umsteigen–umgestiegen", "type": "sentence"}, {"id": "ab091-t13", "text": "Ergänzen Sie haben oder sein und das Partizip in der richtigen Form.", "type": "sentence"}, {"id": "ab091-t14", "text": "Wie war dein Abend? — Sehr gut. Isabella und Tom sind gekommen. Wir haben zusammen eine Fischsuppe gekocht. Später sind wir noch in die Disco gegangen.", "type": "sentence"}, {"id": "ab091-t15", "text": "Und was habt ihr gestern gemacht? — Wir sind in die Stadt gefahren und haben eingekauft.", "type": "sentence"}, {"id": "ab091-t16", "text": "Letztes Jahr sind wir zum Edinburgh Festival geflogen. — Und wie hat es euch gefallen? — Es war super. Wir haben gute Musik gehört und Freunde getroffen.", "type": "sentence"}, {"id": "ab091-t17", "text": "Ich bin mit dem Zug von München nach Flensburg gefahren. — Wie oft bist du umgestiegen? — Nur einmal, in Hamburg.", "type": "sentence"}, {"id": "ab092-t01", "text": "Ergänzen Sie war oder hatte.", "type": "sentence"}, {"id": "ab092-t02", "text": "Heute war ich im Kino. — Und wie war der Film? — Langweilig!", "type": "sentence"}, {"id": "ab092-t03", "text": "Hast du eingekauft? — Nein, ich hatte kein Geld.", "type": "sentence"}, {"id": "ab092-t04", "text": "Hast du kein Obst mehr? — Doch, gestern hatte ich noch Äpfel und Orangen.", "type": "sentence"}, {"id": "ab092-t05", "text": "Wie war die Party? — Schön. Ich hatte viel Spaß.", "type": "sentence"}, {"id": "ab092-t06", "text": "Ein Tagebuch — Teresas Tagebuch. Schreiben Sie im Perfekt.", "type": "sentence"}, {"id": "ab092-t07", "text": "Freitag: Monas Geburtstagsfeier, lange feiern · Samstag: Max holt mich ab, gehen ins Kino, treffen Doro und Jo · Sonntag: lange schlafen, Wohnung aufräumen · Montag: arbeiten, Spanisch lernen · Dienstag: in die Stadt fahren, Kette kaufen", "type": "sentence"}, {"id": "ab092-t08", "text": "Freitag, 15.5. — Ich war auf Monas Geburtstagsfeier, wir haben lange gefeiert.", "type": "sentence"}, {"id": "ab092-t09", "text": "Was haben Sie die letzten Tage gemacht? Schreiben Sie.", "type": "sentence"}, {"id": "ab092-t10", "text": "aus, in oder nach? Kreuzen Sie an.", "type": "sentence"}, {"id": "ab092-t11", "text": "Monique und Jules leben zusammen in Berlin.", "type": "sentence"}, {"id": "ab092-t12", "text": "Monique ist Studentin, sie studiert hier Deutsch. Aber sie kommt aus der Schweiz.", "type": "sentence"}, {"id": "ab092-t13", "text": "Letzten Monat ist sie nach Genf geflogen und hat ihre Eltern besucht.", "type": "sentence"}, {"id": "ab092-t14", "text": "Antoine ist im September nach Deutschland gekommen.", "type": "sentence"}, {"id": "ab092-t15", "text": "Er kommt aus Paris. Sein Deutsch ist nicht so gut. Mit Monique spricht er immer nur Französisch. Aber jetzt macht er einen Deutschkurs.", "type": "sentence"}, {"id": "ab093-t01", "text": "Über eine Party erzählen — Wählen Sie ein Fest aus und sammeln Sie Stichpunkte zu den Fragen.", "type": "sentence"}, {"id": "ab093-t02", "text": "Wann und wo war die Party? · Wer hat eingeladen? · Wer war dort? · Was haben Sie gegessen / getrunken? · Was hat Ihnen gut gefallen?", "type": "sentence"}, {"id": "ab093-t03", "text": "Tipp: Sammeln Sie zuerst Ideen. Schreiben Sie Kärtchen zu verschiedenen Fragen. So können Sie ein Gespräch gut vorbereiten.", "type": "sentence"}, {"id": "ab093-t04", "text": "Erzählen Sie Ihrer Partnerin / Ihrem Partner von dem Fest. Verwenden Sie Ihre Stichpunkte aus a.", "type": "sentence"}, {"id": "ab093-t05", "text": "Die Party war letztes Jahr / am … um … Uhr. · Wir haben bei … gefeiert. · Auf dem Fest waren … Personen. · Wir haben … gegessen/getrunken. · … war wirklich toll. / … hat mir (nicht) gefallen.", "type": "sentence"}, {"id": "ab093-t06", "text": "Beispiel: Die Party war letztes Jahr. Wir haben bei Marion Silvester gefeiert. …", "type": "sentence"}, {"id": "ab093-t07", "text": "Aussprache: vokalisches „r“ — Was hören Sie? Kreuzen Sie an. (CD 1, Track 53)", "type": "sentence"}, {"id": "ab093-t08", "text": "Gruppe „Straße“ – r wie „r“ / Gruppe „Silvester“ – r wie „a“", "type": "sentence"}, {"id": "ab093-t09", "text": "Straße · Silvester · Freund · Reise · Erlebnis · Besucher · Ring · Bier · Restaurant", "type": "sentence"}, {"id": "ab093-t10", "text": "Hören Sie noch einmal und sprechen Sie nach. (CD 1, Track 54)", "type": "sentence"}, {"id": "ab093-t11", "text": "Hören Sie und sprechen Sie dann. (CD 1, Track 55) — Das deutsche Jahr", "type": "sentence"}, {"id": "ab093-t12", "text": "Frühling — März, April, Mai, Rock am Ring", "type": "sentence"}, {"id": "ab093-t13", "text": "Sommer — Juni, Juli, August, Geburtstagsparty", "type": "sentence"}, {"id": "ab093-t14", "text": "Herbst — September, Bier in München, Oktober, November", "type": "sentence"}, {"id": "ab093-t15", "text": "Winter — Dezember, Neujahr, Januar, Februar – Karneval", "type": "sentence"}, {"id": "ab094-t01", "text": "Monate und Jahreszeiten — Wie heißen die Monate? Wie heißen die vier Jahreszeiten?", "type": "sentence"}, {"id": "ab094-t02", "text": "Januar · Februar · März · April · Mai · Juni · Juli · August · September · Oktober · November · Dezember", "type": "sentence"}, {"id": "ab094-t03", "text": "Frühling · Sommer · Herbst · Winter", "type": "sentence"}, {"id": "ab094-t04", "text": "Was ist richtig? Kreuzen Sie an.", "type": "sentence"}, {"id": "ab094-t05", "text": "Ich habe am Wochenende meinen Geburtstag gefeiert.", "type": "sentence"}, {"id": "ab094-t06", "text": "Meine Freundin aus Wien ist auch gekommen.", "type": "sentence"}, {"id": "ab094-t07", "text": "Am Abend sind wir in eine Bar gegangen.", "type": "sentence"}, {"id": "ab094-t08", "text": "Wir haben Freunde getroffen.", "type": "sentence"}, {"id": "ab094-t09", "text": "Später in der Nacht haben wir auch getanzt.", "type": "sentence"}, {"id": "ab094-t10", "text": "Heute ist meine Freundin leider wieder abgefahren.", "type": "sentence"}, {"id": "ab094-t11", "text": "Schreiben Sie Sätze im Perfekt.", "type": "sentence"}, {"id": "ab094-t12", "text": "Lucia ist nach Lübeck gekommen.", "type": "sentence"}, {"id": "ab094-t13", "text": "Im Juli sind wir nach Hamburg gefahren.", "type": "sentence"}, {"id": "ab094-t14", "text": "Der Zug ist um 12.30 Uhr abgefahren.", "type": "sentence"}, {"id": "ab094-t15", "text": "Marcel ist nach Amsterdam geflogen.", "type": "sentence"}, {"id": "ab094-t16", "text": "Ich bin mit Carla ins Kino gegangen.", "type": "sentence"}, {"id": "ab094-t17", "text": "Ergänzen Sie.", "type": "sentence"}, {"id": "ab094-t18", "text": "nicky1980: Hallo Leute, ich fliege im Sommer nach Deutschland. Wo gibt es ein gutes Reggae-Festival?", "type": "sentence"}, {"id": "ab094-t19", "text": "SUNSAMMY: Hi nicky, es gibt viele. Ein Fest heißt „Chiemsee Reggae Summer Festival“. Es ist sehr groß, es kommen 30.000 Besucher. Das Festival gibt es seit 15 Jahren und es dauert 3 Tage. Ach ja, und es ist im August.", "type": "sentence"}, {"id": "ab094-t20", "text": "nicky1980: Hi und danke, sunsammy! Ich war schon auf dem Festival. Es war wirklich super! Ich habe viele nette Leute getroffen und gute Musik gehört.", "type": "sentence"}, {"id": "ab095-t01", "text": "Lernwortschatz — Wie heißen die Wörter in Ihrer Sprache? Übersetzen Sie.", "type": "sentence"}, {"id": "ab095-t02", "text": "Jahreszeiten: der Frühling · der Sommer · der Herbst · der Winter · im Winter / Frühling …", "type": "sentence"}, {"id": "ab095-t03", "text": "Monate: der Januar · der Februar · der März · der April · der Mai · der Juni · der Juli · der August · der September · der Oktober · der November · der Dezember · im Januar / Februar …", "type": "sentence"}, {"id": "ab095-t04", "text": "Feste und Feiern: das Fest · die Hochzeit · der Karneval (Fasching, Fasnacht) · das Neujahr · das Silvester · anfangen · aufhören · feiern · dauern · gefallen · seit", "type": "sentence"}, {"id": "ab095-t05", "text": "Weitere wichtige Wörter: das Bier (Weißbier) · die Leute (Plural) · die Person · geben, es gibt · fliegen · springen · studieren · gestern", "type": "sentence"}, {"id": "ab095-t06", "text": "Tipp: Finden Sie internationale Wörter. Man kann sie leicht verstehen. Vergleichen Sie die Wörter mit Ihrer Muttersprache.", "type": "sentence"}, {"id": "ab095-t07", "text": "Welche Wörter möchten Sie noch lernen? Notieren Sie.", "type": "sentence"}, {"id": "ab096-t01", "text": "Wiederholungsstation: Wortschatz", "type": "sentence"}, {"id": "ab096-t02", "text": "Ergänzen Sie. (Ü = UE, Ä = AE, Ö = OE)", "type": "sentence"}, {"id": "ab096-t03", "text": "Am 31.12. ist Silvester.", "type": "sentence"}, {"id": "ab096-t04", "text": "Er arbeitet am Montag von 7:30 Uhr bis 16 Uhr.", "type": "sentence"}, {"id": "ab096-t05", "text": "An einer Universität kann man studieren.", "type": "sentence"}, {"id": "ab096-t06", "text": "Hier kommt der Zug an: Bahnhof.", "type": "sentence"}, {"id": "ab096-t07", "text": "Nach dem Winter kommt der Frühling.", "type": "sentence"}, {"id": "ab096-t08", "text": "Juli, August, September.", "type": "sentence"}, {"id": "ab096-t09", "text": "Die S-Bahn fährt jeden Tag. Sie fährt täglich.", "type": "sentence"}, {"id": "ab096-t10", "text": "Der 1. Monat im Jahr heißt Januar.", "type": "sentence"}, {"id": "ab096-t11", "text": "Die Zeitung ist nicht interessant, sie ist langweilig.", "type": "sentence"}, {"id": "ab096-t12", "text": "Kai ist erst zwei Monate alt. Er ist noch ein Baby.", "type": "sentence"}, {"id": "ab096-t13", "text": "Bitte Vorsicht an der Bahnsteigkante!", "type": "sentence"}, {"id": "ab096-t14", "text": "Das Jahr hat 12 Monate.", "type": "sentence"}, {"id": "ab096-t15", "text": "Peter hat viel gearbeitet. Jetzt macht er eine Pause.", "type": "sentence"}, {"id": "ab096-t16", "text": "Heute ist Sonntag, gestern war Samstag.", "type": "sentence"}, {"id": "ab096-t17", "text": "Silvi hat Geburtstag. Ich muss noch ein Geschenk kaufen.", "type": "sentence"}, {"id": "ab096-t18", "text": "Verkehr und Reisen — Markieren Sie noch zehn Wörter.", "type": "sentence"}, {"id": "ab096-t19", "text": "Ergänzen Sie die Wörter aus a. — der: Bahnsteig, Bus, Flughafen, Koffer · das: Flugzeug, Gepäck, Gleis, Taxi · die: Bahn, Haltestelle, Straßenbahn", "type": "sentence"}, {"id": "ab096-t20", "text": "Was passt? Ordnen Sie zu und schreiben Sie.", "type": "sentence"}, {"id": "ab096-t21", "text": "ein Geschenk bekommen · die Zeitung lesen · Deutsch lernen · das Zimmer aufräumen · ein Bier trinken · nach Madrid fliegen · ein Fest feiern", "type": "sentence"}, {"id": "ab097-t01", "text": "Wiederholungsstation: Grammatik", "type": "sentence"}, {"id": "ab097-t02", "text": "Notizen. Ordnen Sie zu und ergänzen Sie die Verben in der richtigen Form.", "type": "sentence"}, {"id": "ab097-t03", "text": "Komme um 17.23 an. Holst du mich ab?", "type": "sentence"}, {"id": "ab097-t04", "text": "Ich komme gern und bringe Carlos mit. Ist das o.k.?", "type": "sentence"}, {"id": "ab097-t05", "text": "Die U-Bahn fährt nicht. Ich nehme den Bus. Komme etwas später. Sorry.", "type": "sentence"}, {"id": "ab097-t06", "text": "Wie gefallen dir die Schuhe? Schön, oder? Ich glaube, ich kaufe sie. Was denkst du?", "type": "sentence"}, {"id": "ab097-t07", "text": "Komme erst um acht. Es gibt ein Problem bei der Arbeit.", "type": "sentence"}, {"id": "ab097-t08", "text": "Ergänzen Sie die Präpositionen.", "type": "sentence"}, {"id": "ab097-t09", "text": "Restaurant Schmiediger: Wir haben neue Öffnungszeiten! Ab 1.1. haben wir täglich von 11 Uhr bis 24 Uhr geöffnet.", "type": "sentence"}, {"id": "ab097-t10", "text": "Im August machen wir Urlaub! Ab Montag, 2.9. sind wir wieder für Sie da.", "type": "sentence"}, {"id": "ab097-t11", "text": "Kosmetikstudio Isabel: Liebe Kunden, im Januar sind wir täglich schon ab 9 Uhr für Sie da.", "type": "sentence"}, {"id": "ab097-t12", "text": "Im Chatroom — Ergänzen Sie die Verben im Perfekt.", "type": "sentence"}, {"id": "ab097-t13", "text": "bob13: Warum hast du gestern Abend nicht angerufen?", "type": "sentence"}, {"id": "ab097-t14", "text": "trixi111: Ich habe bis sieben Uhr gearbeitet und dann bin ich nach Hause gefahren.", "type": "sentence"}, {"id": "ab097-t15", "text": "bob13: Ach so!", "type": "sentence"}, {"id": "ab097-t16", "text": "trixi111: Dann habe ich Essen eingekauft, mein Zimmer und die Küche aufgeräumt und E-Mails geschrieben. Und du?", "type": "sentence"}, {"id": "ab097-t17", "text": "bob13: Ich habe am Nachmittag Tennis gespielt und ferngesehen.", "type": "sentence"}, {"id": "ab097-t18", "text": "trixi111: Und am Abend? Was hast du gestern Abend gemacht?", "type": "sentence"}, {"id": "ab097-t19", "text": "bob13: Da bin ich mit Sophie in eine Kneipe gegangen und wir haben ein Bier getrunken.", "type": "sentence"}, {"id": "ab097-t20", "text": "trixi111: Aha! Wer ist denn Sophie? … Hallo Bob, ich habe etwas gefragt?", "type": "sentence"}, {"id": "ab097-t21", "text": "Haben Sie …? / Sind Sie …? Ordnen Sie zu und schreiben Sie.", "type": "sentence"}, {"id": "ab097-t22", "text": "Haben Sie schon einmal Sushi gekocht? · Haben Sie schon einmal eine Nacht am Bahnhof geschlafen? · Haben Sie schon einmal eine ganze Nacht bis zum nächsten Morgen gefeiert?", "type": "sentence"}, {"id": "ab097-t23", "text": "Sind Sie schon einmal Einrad gefahren? · Sind Sie schon einmal in London Auto gefahren? · Sind Sie schon einmal im Sommer Ski gefahren? · Sind Sie schon einmal im Winter in einem See geschwommen? · Sind Sie schon einmal in einem Helikopter geflogen? · Sind Sie schon einmal in den falschen Zug eingestiegen?", "type": "sentence"}, {"id": "ab098-t01", "text": "Selbsteinschätzung — Das kann ich!", "type": "sentence"}, {"id": "ab098-t02", "text": "Ich kann jetzt …", "type": "sentence"}, {"id": "ab098-t03", "text": "… Durchsagen verstehen — Bitte Vorsicht an der Bahnsteigkante. Nächster Halt: Innsbrucker Ring.", "type": "sentence"}, {"id": "ab098-t04", "text": "… am Bahnhof Informationen einholen — Wo fährt der Zug nach Essen ab? — Auf Gleis 10. — Wann kommt der Zug in Hamburg an? — Um 12.48 Uhr.", "type": "sentence"}, {"id": "ab098-t05", "text": "… ein Telefonat beenden — Gut, dann … / Also dann · Bis morgen. / Bis … · Mach's gut! · Auf Wiedersehen! / Tschüss", "type": "sentence"}, {"id": "ab098-t06", "text": "… über meinen Tag sprechen (gestern) — Was hast du gestern gemacht? — Ich habe … und …", "type": "sentence"}, {"id": "ab098-t07", "text": "… über Reisen sprechen — Letztes Jahr war ich in … — Dieses Jahr fahre ich wieder nach …", "type": "sentence"}, {"id": "ab098-t08", "text": "… über Feste sprechen — Letztes Jahr war ich beim Oktoberfest. Das Oktoberfest ist jedes Jahr im Herbst in München und dauert ungefähr zwei Wochen. Es war super. Ich habe viele nette Leute kennen gelernt.", "type": "sentence"}, {"id": "ab098-t09", "text": "Ich kenne … — 5 Verkehrsmittel: Diese Verkehrsmittel nehme ich oft: … Diese Verkehrsmittel nehme ich fast nie / nie: …", "type": "sentence"}, {"id": "ab098-t10", "text": "10 Alltagsaktivitäten: Diese Aktivitäten mache ich gern: … Diese Aktivitäten mache ich nicht gern: …", "type": "sentence"}, {"id": "ab098-t11", "text": "12 Monate und die Jahreszeiten: Monate: … Jahreszeiten: …", "type": "sentence"}, {"id": "ab099-t01", "text": "Ich kann auch …", "type": "sentence"}, {"id": "ab099-t02", "text": "… Informationen einholen und geben (trennbare Verben + Satzklammer) — (am Bahnhof abholen) W-Frage: Wann …? · Ja-/Nein-Frage: Holst du …? · Auskunft: Ja, ich …", "type": "sentence"}, {"id": "ab099-t03", "text": "… einen Zeitraum angeben (temporale Präpositionen von … bis, ab) — Wann hast du heute gearbeitet? — Von 9.00 bis 13.00 Uhr. — Wann übst du Cello? — Ab 16.00 Uhr.", "type": "sentence"}, {"id": "ab099-t04", "text": "… über Vergangenes sprechen (Perfekt + Satzklammer) — (von 9–15 Uhr arbeiten) Wann hast du …? Ich habe gestern … — (am Abend fernsehen) Was hast du … gemacht? Ich … — (nach München fliegen) Wann …? Letztes Jahr …", "type": "sentence"}, {"id": "ab099-t05", "text": "… Zeiten im Jahr angeben (temporale Präposition im) — Wann hast du Geburtstag? — Im Sommer. / Im Juni.", "type": "sentence"}, {"id": "ab099-t06", "text": "Üben / Wiederholen möchte ich noch …", "type": "sentence"}, {"id": "ab099-t07", "text": "Rückblick — Wählen Sie eine Aufgabe zu Lektion 10", "type": "sentence"}, {"id": "ab099-t08", "text": "Sehen Sie die Fotos im Kursbuch auf Seite 59 (Aufgabe 7) an und schreiben Sie kurze Gespräche.", "type": "sentence"}, {"id": "ab099-t09", "text": "Ich komme um 21.45 Uhr an. Dann nehme ich die S-Bahn. — Super, ich hole dich dann am S-Bahnhof ab.", "type": "sentence"}, {"id": "ab099-t10", "text": "Wählen Sie ein Foto und schreiben Sie ein Gespräch.", "type": "sentence"}, {"id": "ab100-t01", "text": "Wählen Sie eine Aufgabe zu Lektion 11", "type": "sentence"}, {"id": "ab100-t02", "text": "Sehen Sie noch einmal das Foto im Kursbuch auf Seite 61 und die Aufgaben 2, 3 und 5 an. Was wissen Sie über Anja?", "type": "sentence"}, {"id": "ab100-t03", "text": "Wählen Sie eine bekannte Person aus Deutschland, Österreich oder aus der Schweiz. Was macht diese Person an einem normalen Montag? Was denken Sie? Machen Sie Notizen und schreiben Sie.", "type": "sentence"}, {"id": "ab100-t04", "text": "Ich glaube, … steht am Montag immer früh auf. Sie / Er …", "type": "sentence"}, {"id": "ab100-t05", "text": "Wählen Sie eine Aufgabe zu Lektion 12", "type": "sentence"}, {"id": "ab100-t06", "text": "Ein Fest/Festival in meinem Land. Sehen Sie noch einmal im Kursbuch auf Seite 66 nach.", "type": "sentence"}, {"id": "ab100-t07", "text": "Ergänzen Sie die Tabelle. — Name? · wo? · seit wann? · wann (Monat) / wie lange?", "type": "sentence"}, {"id": "ab100-t08", "text": "Schreiben Sie einen Text zu Ihrem Fest/Festival ähnlich wie im Kursbuch S. 66, Aufgabe 3.", "type": "sentence"}, {"id": "ab100-t09", "text": "Das Fest heißt … und ist in … Es ist im … Es dauert …", "type": "sentence"}, {"id": "ab100-t10", "text": "Beschreiben Sie ein Fest/Festival in Ihrem Land.", "type": "sentence"}, {"id": "ab100-t11", "text": "Ein Fest in … heißt …", "type": "sentence"}, {"id": "ab101-t01", "text": "Literatur — Paul und Herr Rossmann machen Ferien — Teil 4: Bis bald, Paul!", "type": "sentence"}, {"id": "ab101-t02", "text": "Paul und Anja sind in einem Café am Münchner Hauptbahnhof. Paul trinkt einen Cappuccino und Anja einen Espresso. Zwei Wochen war Paul in München. Jetzt fährt er wieder nach Wien.", "type": "sentence"}, {"id": "ab101-t03", "text": "„Wie spät ist es?“, fragt Anja. — „13:35 Uhr“, sagt Paul. — „Und wann fährt dein Zug?“ — „Um 14:02 Uhr.“ — „Oh je, wir haben nicht mehr viel Zeit.“", "type": "sentence"}, {"id": "ab101-t04", "text": "„Ich finde, wir hatten zwei sehr schöne Wochen zusammen“, sagt Paul. — „Ja, das finde ich auch. Was hat dir besonders gut gefallen in München, Paul?“", "type": "sentence"}, {"id": "ab101-t05", "text": "„Hmm … ich weiß nicht … Mir haben viele Dinge gefallen: das Rathaus, die Frauenkirche, das Olympiastadion, der Englische Garten … Und in der Disco hat es mir sehr gut gefallen. Du tanzt wirklich super …“", "type": "sentence"}, {"id": "ab101-t06", "text": "„Oh, danke! Du tanzt aber auch nicht schlecht“, sagt Anja. — „Auch das Oktoberfest war toll.“ — „Das hat dir wirklich so gut gefallen?“ — „Ja, wirklich. Ich mag Brezen und Bier.“", "type": "sentence"}, {"id": "ab101-t07", "text": "Herr Rossmann bellt. — „Ich weiß, dir hat das Oktoberfest keinen Spaß gemacht“, sagt Anja. „Zu viele Leute, zu viel Bier, zu laute Musik.“", "type": "sentence"}, {"id": "ab101-t08", "text": "„Und was hat dir besonders gut gefallen, Anja?“ — „Der lange Spaziergang gestern … Wir haben viel geredet. Das war sehr schön.“ — „Ja, das war wirklich schön.“", "type": "sentence"}, {"id": "ab101-t09", "text": "Paul und Anja sehen sich lange an. Paul nimmt Anjas Hand und …", "type": "sentence"}, {"id": "ab101-t10", "text": "„VORSICHT AUF GLEIS ZWEI! IN FÜNF MINUTEN FÄHRT DER ZUG NACH WIEN AB!“", "type": "sentence"}, {"id": "ab101-t11", "text": "„Ach, warum gerade jetzt?“, denkt Paul. Herr Rossmann bellt. — „Ja, ich weiß, Herr Rossmann, unser Zug ist da. Ich komme ja schon“, sagt Paul.", "type": "sentence"}, {"id": "ab101-t12", "text": "Sie gehen gemeinsam zum Bahnsteig. — „Möchtest du nicht noch in München bleiben?“, fragt Anja. „Eine Woche oder zwei …?“ — „Ich möchte gern, aber ich habe morgen einen Termin in Wien.“", "type": "sentence"}, {"id": "ab101-t13", "text": "„Rufst du mich an?“ — „Ja, ich rufe dich an. Schreibst du mir mal eine E-Mail?“ — „Ich schreibe dir viele E-Mails.“", "type": "sentence"}, {"id": "ab101-t14", "text": "„Besuchst du mich einmal in Wien?“, fragt Paul. — „Oh ja, das ist eine gute Idee. Ich komme gern nach Wien.“", "type": "sentence"}, {"id": "ab101-t15", "text": "„VORSICHT AUF GLEIS ZWEI! IHR ZUG FÄHRT JETZT AB!“", "type": "sentence"}, {"id": "ab101-t16", "text": "Paul und Herr Rossmann steigen ein. — „Also, mach's gut, Paul.“ — „Du auch, pass auf dich auf! Bis bald.“ — „Ja, bis bald.“", "type": "sentence"}, {"id": "ab101-t17", "text": "Herr Rossmann bellt. — „Tschüs, Herr Rossmann. Bis bald!“ — Der Zug fährt ab.", "type": "sentence"}]);

